/* spawn ground debris/dust particles around a car */
void func_000412D4(int car, short height, int type)
{
    VECTOR pos;
    SURF surf;
    int count;
    int idx;
    PARTICLE_f412D4 *p;

    if (*(int *)&pauseflag)
        return;

    count = 15;
    if (type)
        count = 20;

    while (count-- != 0) {
        if (type) {
            pos.vx = (func_000776E4() & 0x1FF) - 256;
            pos.vz = func_000776E4() % 1024 - 512;
        } else {
            pos.vx = (func_000776E4() & 0x1FF) - 256;
            pos.vz = (func_000776E4() & 0x400) - 512;
        }
        SetRotMatrix(&D_000AF6A0[car]);
        func_0004EAC0(&pos);
        pos.vx += car_data[car].pos.vx;
        pos.vy = -height;
        pos.vz += car_data[car].pos.vz;

        idx = func_00042678();
        if (idx < 0)
            return;

        if (type) {
            if (ROADS_GetRouteData(pos.vx, pos.vz, &surf) && (*modelpointers[surf.type] & 0x80)) {
                p = &((PARTICLE_f412D4 *)D_000B92A0)[idx];
                p->pos = pos;
                p->flags = 0x8006;
                p->s3C = 200;
                p->s3E = (func_000776E4() & 7) + 5;
                p->s38 = 300;
                p->s3A = 700;
                p->i40 = 10;
                p->b44 = 100;
            }
        } else {
            p = &((PARTICLE_f412D4 *)D_000B92A0)[idx];
            p->pos = pos;
            p->flags = 6;
            p->s3C = 200;
            p->s3E = (func_000776E4() & 15) + 10;
            p->s38 = 100;
            p->i40 = 10;
            p->s3A = 200;
            p->b44 = 50;
        }
    }
}

