/* ---------------- func_00046000 (src/pilot/func_00046000.c) ---------------- */
void func_00046000(int player)
{
    SVECTOR v;
    CVECTOR col;
    unsigned char *flash;
    int side, j, k, sign, size;
    int c;

    sign = 1;
    flash = &CARS_AT(D_0009B1D4, 0x130)[player].f131;
    if (*(int *)&D_0009688C == player && *(unsigned char *)&(*(long long *)&cameraview) == 2)
        return;
    if (*(int *)&FastForward != 0)
        return;
    if (CARS_AT(D_0009B1D4, 0x130)[player].where.m[1][1] < 100)
        return;
    k = (D_00097488 + player) & 7;
    for (side = 1; side != -1; side--) {
        for (j = 2; j != -1; j--) {
            v.vx = D_0008A8D8[k] * sign;
            v.vy = -164;
            c = 90;
            if (*(int *)&gNight != 0)
                c = 50;
            if (*(int *)&pauseflag == 0 && (*(int *)&CameraCnt & 1))
                k++;
            v.vz = 15;
            k &= 7;
            size = (*flash < 128 ? *flash : 255 - *flash) >> 1;
            if (side) {
                col.r = 255;
                col.g = c;
                col.b = c;
            } else {
                col.r = c;
                col.g = c;
                col.b = 255;
            }
            if (*(int *)&pauseflag == 0)
                *flash += 16;
            ((void (*)())func_00043FDC)(&v, player, &col, size, ((char *)&D_000B9210), 255);
            if (*(int *)&pauseflag == 0 && (*(int *)&CameraCnt & 1))
                k++;
            k &= 7;
        }
        sign = -sign;
    }
}

